import type { ComponentProps } from "react";
import "./radio.css";

export type RadioProps = Omit<ComponentProps<"input">, "type">;

export function Radio(props: RadioProps) {
  return (
    <span data-slot="radio-root">
      <input data-slot="radio" {...props} type="radio" />
      <span data-slot="radio-indicator" aria-hidden="true" />
    </span>
  );
}

/* radio.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* The native input fills the target; the smaller indicator is decorative. */
  [data-slot="radio-root"] {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: var(--control-height);
    height: var(--control-height);
    vertical-align: middle;
  }

  [data-slot="radio"] {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    appearance: none;
    border: 0;
    background: transparent;
    outline: none;
    cursor: pointer;
    touch-action: manipulation;
  }

  /* Choice marks: one 18px recessed mark for checkbox and radio. Checked
     marks fill with ink; the check stroke draws itself and the radio dot
     settles in. The switch thumb stretches while pressed, then settles. */
  [data-slot="radio-indicator"] {
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
    pointer-events: none;
    background: var(--field);
    box-shadow: var(--shadow-field);
    transition:
      background-color var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  [data-slot="radio-indicator"] {
    width: 18px;
    height: 18px;
  }
  [data-slot="radio-indicator"] {
    border-radius: 50%;
  }

  [data-slot="radio"]:checked + [data-slot="radio-indicator"] {
    background: var(--accent);
    box-shadow: 0 0 0 1px var(--accent), inset 0 1px 0 rgb(255 255 255 / 14%);
  }

  [data-slot="radio-indicator"]::after {
    content: "";
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--accent-foreground);
    transform: scale(0);
    transition: transform 240ms var(--ease-settle);
  }
  [data-slot="radio"]:checked + [data-slot="radio-indicator"]::after {
    transform: scale(1);
  }

  @media (hover: hover) {
    [data-slot="radio"]:hover:not(:disabled):not(:checked) + [data-slot="radio-indicator"] {
      box-shadow: var(--shadow-field-hover);
    }
  }

  [data-slot="radio"]:focus-visible + [data-slot="radio-indicator"] {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }

  [data-slot="radio"][aria-invalid="true"] + [data-slot="radio-indicator"] {
    box-shadow: var(--shadow-field-invalid);
    outline-color: var(--destructive);
  }

  [data-slot="radio"]:disabled {
    cursor: not-allowed;
  }
  [data-slot="radio"]:disabled + [data-slot="radio-indicator"] {
    background: var(--sunken);
    box-shadow: var(--shadow-field-quiet);
    color: var(--muted-foreground);
  }
  [data-slot="radio"]:disabled:checked + [data-slot="radio-indicator"] {
    background: var(--border);
    box-shadow: none;
  }
  [data-slot="radio"]:disabled + [data-slot="radio-indicator"]::after {
    background: var(--muted-foreground);
  }

  @media (forced-colors: active) {
    [data-slot="radio-indicator"] {
      forced-color-adjust: none;
      background: Canvas;
      border-color: CanvasText;
    }
    [data-slot="radio-indicator"] {
      border: 1px solid CanvasText;
      box-shadow: none;
    }
    [data-slot="radio"]:checked + [data-slot="radio-indicator"] {
      background: Canvas;
      border-color: CanvasText;
    }
    [data-slot="radio"]:checked + [data-slot="radio-indicator"]::after {
      background: CanvasText;
    }
    [data-slot="radio"]:hover:not(:disabled) + [data-slot="radio-indicator"] {
      border-color: CanvasText;
    }
    [data-slot="radio"]:focus-visible + [data-slot="radio-indicator"] {
      outline-color: Highlight;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="radio-indicator"],
    [data-slot="radio-indicator"]::after {
      transition: none;
    }
  }
}
